#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Reflection;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public sealed class RagusaEnvoyCapture:MonoBehaviour
{
 string folder;int checks;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Begin(){if(!Environment.GetCommandLineArgs().Contains("-ragusa-envoy-capture"))return;var go=new GameObject("Ragusa envoy checks");DontDestroyOnLoad(go);go.AddComponent<RagusaEnvoyCapture>();}
 void Check(bool yes,string message){if(!yes)throw new Exception(message);checks++;}
 void Envoy(int state)=>VariableSingleton.SetInt("iDiplomacyEnvoy_"+CountryDiplomacy.Index("ragusa"),state);
 IEnumerator Start(){folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/RagusaEnvoy"));Directory.CreateDirectory(folder);SaveGames.TestRoot=Path.Combine(folder,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.json");var run=Run();while(true){object next=null;bool more=false;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"checks.txt"),"FAILED "+checks+"\n"+ex);Application.Quit(1);yield break;}if(!more)break;yield return next;}File.WriteAllText(Path.Combine(folder,"checks.txt"),checks+" Ragusa envoy/agreement checks passed");Application.Quit(0);}
 IEnumerator Run(){yield return null;SaveMenu.StartCampaign(false);yield return new WaitForSecondsRealtime(2);CampaignHUD.Instance.DismissReport();var council=FindObjectOfType<CouncilUI>(true);CountryDiplomacy.Ensure();VariableSingleton.SetInt("iMoney",100000);VariableSingleton.SetInt("iCavalry",500);var baseline=VariableSingleton.Instance.CaptureState();
 foreach(int state in new[]{0,1,3}){Envoy(state);int gold=CouncilActions.Int("iMoney"),foot=CouncilActions.Int("iInfantry");string rng=JsonUtility.ToJson(UnityEngine.Random.state);Check(!RagusaDiplomacy.RequestFood(out _)&&!RagusaDiplomacy.StartContract(out _),"non-resident cannot sign "+state);Check(CouncilActions.Int("iMoney")==gold&&CouncilActions.Int("iInfantry")==foot&&JsonUtility.ToJson(UnityEngine.Random.state)==rng,"rejected agreements do not spend or roll");}
 foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1600,900)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.3f);
 foreach(int state in new[]{0,1,2,3}){Envoy(state);for(int month=0;month<(state==2?2:1);month++){typeof(VariableSingleton).GetField("turn",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,month);council.RagusanCourt();yield return null;Canvas.ForceUpdateCanvases();var root=GameObject.Find("Council screen");var art=GameObject.Find("Ragusan court painting").GetComponent<RawImage>();Check(art.texture!=null,"painting loaded");var labels=root.GetComponentsInChildren<TMP_Text>();string all=string.Join(" ",labels.Select(t=>t.text));foreach(var label in labels)Check(!label.isTextOverflowing,"text fits "+label.text);
 if(state==2){Check(GameObject.Find("Ragusan current negotiator")!=null&&root.GetComponentsInChildren<LocationHotspot>().Length==1,"one active negotiator");string other=RagusaDiplomacy.RepresentativeName(1-RagusaDiplomacy.ActiveRepresentative);Check(all.Contains(RagusaDiplomacy.ActiveRepresentativeName)&&!all.Contains(other),"only current representative named");Check(labels.Any(t=>t.text=="Arrange a private provision shipment")&&labels.Any(t=>t.text=="Hire out troops to Ragusa"),"detailed operations available");}
 else{Check(GameObject.Find("Ragusan conversation")==null&&root.GetComponentsInChildren<LocationHotspot>().Length==0,"no negotiators before residence or after recall");Check(!all.Contains("Johannes")&&!all.Contains("Benedetto"),"no hidden representative names");Check(!labels.Any(t=>t.text=="Arrange a private provision shipment"||t.text=="Hire out troops to Ragusa"),"detailed operations hidden");Check(art.texture==Resources.Load<Texture2D>("UI/Diplomacy/Ragusa/WaitingTerrace"),"empty terrace selected");}
 if(state==0||state==2){ScreenCapture.CaptureScreenshot(Path.Combine(folder,"ragusa-"+size.x+"-"+state+"-"+month+".png"));yield return new WaitForSecondsRealtime(.15f);}
 var back=root.GetComponentsInChildren<Button>().Single(b=>b.GetComponentInChildren<TMP_Text>().text=="Return to War Beyond the Walls");back.onClick.Invoke();yield return null;Check(GameObject.Find("War Beyond the Walls map")!=null&&!root.activeSelf,"Return opens theatre map");WarTheatreUI.Close();}}
 }
 VariableSingleton.Instance.RestoreValidated(baseline);Envoy(2);double stock=SharedProvisions.Stock(SharedProvisions.City);Check(RagusaDiplomacy.RequestFood(out _),"resident signs shipment");Check(CountryDiplomacy.Recall(CountryDiplomacy.Index("ragusa"),out _),"recall after food agreement");Check(RagusaDiplomacy.FoodAtSea&&!RagusaDiplomacy.EnvoyPresent,"cargo remains after recall");
 SaveGames.Checkpoint();var saved=SaveGames.Read(VariableSingleton.SavePath);VariableSingleton.Instance.RestoreValidated(saved.campaign);Check(RagusaDiplomacy.FoodAtSea&&!RagusaDiplomacy.EnvoyPresent,"food and absent envoy persist in save");RagusaDiplomacy.Advance(VariableSingleton.GetDate().AddDays(14));RagusaDiplomacy.Advance(VariableSingleton.GetDate().AddDays(14));Check(SharedProvisions.Stock(SharedProvisions.City)==stock+500,"food delivers once without envoy");
 Envoy(2);int infantry=CouncilActions.Int("iInfantry");Check(RagusaDiplomacy.StartContract(out _),"resident signs troop contract");Check(CountryDiplomacy.Recall(CountryDiplomacy.Index("ragusa"),out _),"recall after troop agreement");Check(RagusaDiplomacy.ContractActive&&!RagusaDiplomacy.EnvoyPresent,"contract persists after recall");SaveGames.Checkpoint();saved=SaveGames.Read(VariableSingleton.SavePath);VariableSingleton.Instance.RestoreValidated(saved.campaign);Check(RagusaDiplomacy.ContractActive&&!RagusaDiplomacy.EnvoyPresent,"contract and recall save/load");RagusaDiplomacy.Advance(VariableSingleton.GetDate().AddDays(90));Check(TrainingPool.Orders.Any(o=>o.kind==RagusaDiplomacy.ExpeditionReturn),"contract resolves without envoy");TrainingPool.CompleteDueOrders(VariableSingleton.GetDate().AddDays(104));RagusaDiplomacy.Advance(VariableSingleton.GetDate().AddDays(104));Check(!RagusaDiplomacy.ContractActive&&CouncilActions.Int("iInfantry")>infantry-500,"survivors return without envoy");
 }
}
#endif
